OUT = ROOT / 'dist'
DOMAIN = 'https://rkpurilaw.com'

def href(path):
    return path if path == '/' else path.rstrip('/') + '/'

def link(path, label, cls=''):
    return f'<a class="{cls}" href="{href(path)}">{label}</a>'

def layout(path, title, description, body, crumb=None, schema=None):
    canonical = DOMAIN + href(path)
    nav = [('Home','/'),('About','/about'),('Practice Areas','/practice-areas'),('Experience','/investigation-expertise'),('Courts & Forums','/courts-and-forums'),('Insights','/insights'),('Contact','/contact')]
    nav_html = ''.join(f'<a href="{href(p)}" class="{"active" if p==path else ""}">{n}</a>' for n,p in nav)
    crumbs = '' if not crumb else '<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>' + ''.join(f'<span>{escape(c)}</span>' for c in crumb) + '</nav>'
